"""Render engineering simulation results and a human-readable scope report.
Script provenance is retained here and in HDF5 metadata, not in figures.
"""
from pathlib import Path
import json,hashlib,sys
import numpy as np
import h5py
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'validation/end-to-end';DOC=ROOT/'docs'
s=json.loads((OUT/'summary.json').read_text());r=json.loads((OUT/'reference-tracking-summary.json').read_text());v=json.loads((OUT/'paired-validation-summary.json').read_text());b=json.loads((OUT/'broadband-summary.json').read_text())
normal=[x for x in s['cases'] if x['fault'] is None]
checks=dict(normal_markers_under_1us=all(x['marker_timing_rms_ns']<1000 for x in normal),normal_average_clock_error_under_0_01ppm=all(abs(x['clock_average_error_ppm'])<.01 for x in normal),sample_drop_flagged=next(x['capture_discontinuity_flag'] for x in s['cases'] if x['fault']=='sample_drop'),overload_flagged=next(x['overload_flag'] for x in s['cases'] if x['fault']=='clipping'),source_phase_normalization=.5<s['checks']['phase_noise_variance_ratio']<2,steering_phase_continuity=s['checks']['phase_continuity_pass'],numerical_32x_to_64x_under_25ns=v['convergence'][-1]['difference_from_previous_rms_ns']<25,reference_observer_error_under_0_03hz=all(x['reference_estimate_error_rms_hz']<.03 for x in r['cases'] if x['gain_error_fraction']==0))
(OUT/'checks.json').write_text(json.dumps(dict(scope='Assertions on specified behavioral scenarios, not hardware qualification',checks=checks,all_pass=all(checks.values())),indent=2)+'\n')
assert all(checks.values()),checks
paths=['tools/end_to_end.py','tools/simulate_reference_tracking.py','tools/simulate_broadband.py','tools/validate_end_to_end.py','tools/report_end_to_end.py','tools/run_end_to_end.py','firmware/main.py','firmware/protocol.py','host/calibration.py','host/tracking.py','cad/design.json','cad/calinject.kicad_pcb']
provenance=dict(python=sys.version,numpy=np.__version__,source_sha256={p:hashlib.sha256((ROOT/p).read_bytes()).hexdigest() for p in paths},data_sha256={p.name:hashlib.sha256(p.read_bytes()).hexdigest() for p in OUT.glob('*.h5')})
(OUT/'provenance.json').write_text(json.dumps(provenance,indent=2)+'\n')
plt.rcParams.update({'font.size':10,'axes.spines.top':False,'axes.spines.right':False})
off=np.geomspace(10,100000,500);points=np.array(s['assumptions']['offset_hz']);typ=np.interp(np.log10(off),np.log10(points),s['assumptions']['phase_noise_typ_dbc_hz'])
fig,ax=plt.subplots(figsize=(7,4.3))
ax.semilogx(off,typ,label='10 MHz oscillator, typical')
ax.semilogx(off,typ+20*np.log10(7),label='70 MHz harmonic, ideal multiplication')
white=10*np.log10((2*np.pi*10e6*20e-12)**2/10e6)
combined=10*np.log10(10**(typ/10)+10**(white/10))+20*np.log10(7)
ax.semilogx(off,combined,'--',label='70 MHz + assumed 20 ps/edge noise')
ax.set(xlabel='Offset frequency (Hz)',ylabel='SSB phase noise (dBc/Hz)');ax.grid(alpha=.2);ax.legend(fontsize=9);fig.tight_layout();fig.savefig(DOC/'phase-noise.png',dpi=180);plt.close(fig)
with h5py.File(OUT/'results.h5') as h:
 fig,axs=plt.subplots(2,2,figsize=(9,6.5))
 hz=h['plant/frequency_error_hz'][:];phase=h['plant/phase_error_cycles'][:];code=h['plant/dac_code'][:]
 axs[0,0].plot(np.arange(len(hz))/60,hz,lw=1);axs[0,0].set(xlabel='Time (min)',ylabel='10 MHz frequency error (Hz)')
 axs[0,1].plot(np.arange(len(phase))/60,phase,lw=1);axs[0,1].set(xlabel='Time (min)',ylabel='Phase relative to ideal 10 MHz (cycles)')
 for ax in axs[0]:
  ax.axvspan(1000/60,1060/60,color='orange',alpha=.15);ax.axvspan(1820/60,1826/60,color='orange',alpha=.15)
 tt=h['steering/time_relative_s'][:];zz=h['steering/frequency_error_hz'][:];pp=h['steering/phase_error_cycles'][:]
 axs[1,0].plot(tt*1000,zz);axs[1,0].set(xlabel='Time after DAC update (ms)',ylabel='10 MHz frequency error (Hz)')
 axs[1,1].plot(tt*1000,pp-pp[0]);axs[1,1].set(xlabel='Time after DAC update (ms)',ylabel='Accumulated phase change (cycles)')
 for ax in axs.flat:ax.grid(alpha=.2)
 fig.tight_layout();fig.savefig(DOC/'servo-phase.png',dpi=180);plt.close(fig)
 fig,axs=plt.subplots(3,1,figsize=(8,7))
 with h5py.File(OUT/'broadband.h5') as bb:
  for ax,name in zip(axs,['HF25','HF50','meteor']):
   ff=bb[name+'/frequency_hz'][:]/1e6;power=bb[name+'/power_dbm_per_fft_bin'][:]
   ax.plot(ff,power,lw=.7);ax.set(ylabel='Power (dBm/bin)',xlabel=('Baseband frequency (MHz)' if name=='meteor' else 'RF / aliased frequency (MHz)'),ylim=(-145,-65))
   ax.text(.02,.93,name,transform=ax.transAxes,va='top');ax.grid(alpha=.2)
 fig.tight_layout();fig.savefig(DOC/'broadband-simulation.png',dpi=180);plt.close(fig)

lines=['# End-to-end behavioral simulation','','The simulation now connects GPS/PPS events, the actual frequency servo, loaded DAC filtering, continuous oscillator phase, harmonic phase noise, adjustable injection level, generic receiver filtering, ADC-clock drift and quantization, marker detection, sample-rate fitting, and science-frequency recovery. It also tests an offline reference tracker and applies a phase-continuous correction to synthetic IQ. **These are modeled results, not measured board or receiver performance.**','','## USB controls and steering','','Already supported: electronic attenuation 0–31.5 dB in 0.5 dB steps, burst length 1–900,000 µs, mute/burst/continuous modes, servo enable, manual DAC code, slope calibration, status and explicit settings save. The dedicated PPS SMA stays at its configured 10 ms GNSS width; `width` changes the RF burst. The physical LOW/HIGH range shunts add/bypass another 20 dB; USB does not move those shunts. Example JSON commands:','','```json','{"cmd":"atten","db":20}','{"cmd":"width","us":1000}','{"cmd":"save"}','```','','The hardware oscillator is never phase-reset by these commands. The existing servo updates a DAC target every 64 valid seconds; the two RC sections turn that voltage change into a frequency ramp. Phase remains the integral of frequency. There is no programmable firmware slew-rate command in this release. Supply feedthrough, DAC glitches, and comparator threshold changes could still perturb real phase and need measurement. A manual DAC command disables the automatic servo.','','## Phase-noise budget','','The [ECS datasheet](https://ecsxtal.com/store/pdf/ECS-TXO32-S3.pdf) specifies these oscillator phase-noise points at 10 MHz. They apply to a continuous carrier; burst gating adds deterministic sidebands and must not be mistaken for oscillator phase noise.','','| Offset | Typical at 10 MHz | Maximum column at 10 MHz | Ideal typical at 70 MHz |','|---|---:|---:|---:|']
for f,p in zip(points,s['assumptions']['phase_noise_typ_dbc_hz']):lines.append(f'| {f:g} Hz | {p:g} dBc/Hz | {p+5:g} dBc/Hz | {p+20*np.log10(7):.1f} dBc/Hz |')
lines+=['','The nth harmonic multiplies phase fluctuations by n: phase-noise power rises by 20 log10(n), while the corresponding time jitter is unchanged. Comparator, logic, supply and buffer noise add to that. The model sweeps assumed 20 and 100 ps independent per-edge noise; neither is a guaranteed board jitter value. The time/phase relation uses Sφ(f) = 2 × 10^(L(f)/10) for the one-sided phase PSD.','','![Continuous-carrier phase-noise budget](phase-noise.png)','',f'Log-log interpolation of the published points gives {s["intrinsic_10hz_to_100khz_jitter_ps"]["typ"]:.2f} ps typical and {s["intrinsic_10hz_to_100khz_jitter_ps"]["max_points_interpolated"]:.2f} ps using the maximum column, integrated only from 10 Hz to 100 kHz. These are interpolation calculations, not an integrated-jitter guarantee. Noise below 10 Hz, above 100 kHz and additive board noise are not bounded by those figures.','','## What software tracking gains','','The onboard loop keeps the oscillator near 10 MHz; it does not phase-lock it to PPS. In this run the slow thermal perturbation and 64 s updates leave a larger reference error than the earlier ideal white-noise-only test. The software observer uses the integer GPS edge counts and logged DAC targets, reconstructs the loaded RC response, then fits residual phase over a centered 64 s window. It does not use the true oscillator frequency to form its estimate.','','The centered fit needs future data: it is an offline smoother, not a zero-latency real-time tracker. UTC correspondence must already be resolved. A live predictor would have a different error/latency budget. The observer is a simulation prototype rather than an automatic production capture pipeline.','','For the 70 MHz meteor case, 20 dB electronic attenuation:','','| Burst | Marker RMS error | Science frequency RMS before reference tracking | After reference tracking |','|---|---:|---:|---:|']
for width in [100,1000,10000]:
 core=next(x for x in s['cases'] if x['profile']=='meteor' and x['width_us']==width and x['attenuation_db']==20 and x['fault'] is None and x['edge_jitter_assumed_ps']==20 and x['phase_noise_margin_db']==0)
 obs=next(x for x in r['cases'] if x['profile']=='meteor' and x['width_us']==width and x['attenuation_db']==20 and x['gain_error_fraction']==0)
 lines.append(f'| {width/1000:g} ms | {core["marker_timing_rms_ns"]:.0f} ns | {obs["science_error_before_rms_hz"]:.3g} Hz | {obs["science_error_after_rms_hz"]:.3g} Hz |')
obs=next(x for x in r['cases'] if x['profile']=='meteor' and x['width_us']==10000 and x['attenuation_db']==20 and x['gain_error_fraction']==0)
lines+=['',f'The reference-frequency estimate itself has {obs["reference_estimate_error_rms_hz"]:.4f} Hz RMS error at 10 MHz in that modeled interval. Multiplying it by seven supplies the estimated actual 70 MHz pilot frequency for science-frequency recovery. Results include ±10% assumed tuning-gain sensitivity for this scenario; they do not bound arbitrary thermal histories, supply noise or tuning nonlinearity.','','`host/tracking.py` integrates a piecewise-linear frequency track analytically, producing continuous phase and frequency at every knot. It never unwraps carrier phase across the 1 s gaps. The paired validation applies this correction to actual synthetic IQ using estimated sample times, then remeasures the science tone. Tests also check a chirp across knot boundaries. Continuous interpolation does not recover unobserved integer-cycle ambiguities or establish absolute carrier-phase coherence between bursts. The coherent frequency estimator avoids the isolated phase-unwrapping failures seen in the earlier averaging sweep, but still needs a properly isolated pilot and can select a strong interferer.','','![Frequency steering and continuous phase](servo-phase.png)','','Orange intervals indicate modeled GPS-invalid periods. DAC updates change frequency smoothly through the RC response; the phase curve is not steered back to zero.','','## Receiver and signal assumptions','','Three cases are simulated: direct-sampled HF with 64 MS/s and a 10 MHz pilot; direct-sampled wider HF with 128 MS/s and a 40 MHz pilot; and a 2 MS/s tuned meteor receiver containing the 70 MHz pilot. Each is analyzed in an equivalent 1 MS/s complex channel. These are RX888-like/RTL-like configurations, not calibrated hardware models. A generic 350 kHz low-pass channel, assumed aperture jitter and gain, and equivalent 16/8-bit quantization are included.','','The science signal is an isolated −86 dBm tone 150 kHz above the selected harmonic, measured for 10 ms outside the calibration burst. The pilot is recovered inside the burst after filter transients are trimmed. A training template and coarse acquisition frequency are assumed; the fine arrival and frequency are estimated from noisy data. The simulations use explicitly associated UTC epochs, not USB arrival timestamps. They do not resolve the integer-second ambiguity automatically.','','The background is −96 dBm per 1 MHz equivalent channel before filtering. LOW range and electronic attenuation of 20 or 31.5 dB give different pilot SNRs at each harmonic. Pilot levels come from the ideal 10 ns pulse model, not a measured RF transfer function. Prior 7/10/12 ns pulse-width sensitivity, passive SPICE and cable-driver simulations remain separate checks linked from the simulation/layout reports.','','The ADC clock starts 3 ppm fast and drifts by 0.002 ppm/s; the tuner LO starts 100 Hz off and drifts by 0.02 Hz/s. Generic tuner phase noise is explicitly assumed. The two-pole DAC filter includes the specified minimum 100 kΩ control-input load, giving a 0.9804 DC gain; commissioning must measure Hz/code at the actual oscillator. GPS jitter is assumed 20 ns RMS, PIO synchronization is quantized in 8 ns steps, and the first RF pulse has a 0–100 ns phase-dependent delay. Fixed path delay is assumed known and subtracted.','','The core run has 23 cases: three receiver profiles × three widths × two attenuations, plus GPS loss, sample loss, overload, and two phase-noise sensitivities. Every normal case spans 64 possible PPS epochs, including a GPS-invalid interval. The paired check repeats sensitivity cases with identical random noise so parameter changes can be distinguished from Monte Carlo scatter. Numerical timing convergence is checked at 16×, 32× and 64× waveform oversampling.','','## Discontinuities, overload and aliases','','GPS-invalid epochs suppress bursts while the reference oscillator continues. This models invalid UTC flags before arming; antenna-loss detection latency and a burst already armed before a late fault remain hardware/firmware acceptance checks. A 4096-native-sample recording drop produces a large fit residual and is flagged: analysis must split at the discontinuity. The overload scenario is also flagged and excluded from usable results even if a frequency fit happens to look plausible. These flags describe the simulation analysis; actual recording software must inspect raw clipping and sample-loss metadata. One affine clock fit across the whole drift interval is insufficient; short-window rate fits are used for correction.','','Native-rate real HF and complex meteor snapshots include twenty comb harmonics (through 200 MHz), carrier response of generic sixth-order anti-alias filters, broadband noise, a science tone and 16/8-bit quantizers. They demonstrate how harmonics outside Nyquist can fold into the recording. Actual RX888/RTL filter curves, ENOB, nonlinearity and out-of-band response must be measured. Analogue gate/filter transients in these broadband snapshots are simplified to per-carrier responses. The main marker model uses a time-domain receiver filter.','','![Quantized native-rate broadband snapshots](broadband-simulation.png)','','The RF comb is not bandlimited to 70 MHz. Harmonics above 200 MHz are omitted from these snapshots. The injected spectrum and the receiver anti-alias path both need bench checks.','','## Antenna leakage and other physical limits','','The RF combiner is represented by nominal 3.2 dB forward loss; it is not an extracted three-port PCB/transformer model. With 20 dB branch isolation and a matched SDR, calibration leaking toward the antenna can be only 16.8 dB below the level delivered to the SDR. Receiver mismatch can make isolation worse. The separate layout review documents finite isolation, the shared quiet/fast-logic rail and lack of ferrite filtering. No simulation here establishes negligible radiation or muted clock feedthrough.','','Unknowns still requiring first-article measurements include actual GNSS timing, DAC gain/nonlinearity/glitches, oscillator supply pushing, comparator/logic jitter, pulse width, harmonic levels, RF matching/isolation, board coupling, regulator stability, USB-induced spurs, cable delays, receiver group delay and gain, and real interference. There is no full transistor-level board, electromagnetic, GNSS RF, ARM firmware or USB-stack emulation. Actual UBX framing/UTC validity, the servo code and host estimators are reused; PIO/compiler, USB queue, cable-driver SPICE and CAD checks are additional independent validations.','','## Reproduce and inspect','','```sh','conda run -n base python tools/run_end_to_end.py','conda run -n base python -m unittest discover -s tests -v','```','','HDF5 stores synthetic samples, marker positions, reference counts, DAC states, recovered frequencies, phase corrections, spectra and assumptions. JSON summaries accompany the arrays in `validation/end-to-end/`. These artifacts contain no bench data. [Earlier simulations](simulation.md) · [Averaging tradeoff](averaging.md) · [Layout and power review](layout-review.md) · [Hardware acceptance](acceptance.md).','']
(DOC/'end-to-end.md').write_text('\n'.join(lines))
print('Report and three figures written')
